"""X-MFG-40 in-house code intent for every graph unit (AQS-ASME-002). Design pressure from the graph (params.design_kPa, gauge; pressure
nodes from flow_graph/param/pressure_nodes.py), design temperature from params.design.T_C (else ambient), inside diameter from params.design.
Rules (ASME_VIII1_U1): P <= 103 kPa g -> atmospheric (outside Section VIII; thermoplastic tanks to DVS2205, steel to API 650/620 intent);
ID <= 152 mm at higher pressure -> outside Section VIII by size, designed as a piping component to ASME_B31_3 with the UG-27 check already made;
otherwise Section VIII Division 1 (in-house design, no stamp in this study). Replaces the "Vendor" class. Run: python3 docs-authority/_asme_class.py"""
import collections, json, os
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
MACHINES = {'EXPANDER': 'reciprocating expander, cylinder and head are parts of the machine (models/mfg/EXPANDER); hydrotest 1.5 x 550 kPa g'}
def main():
    g = json.load(open(os.path.join(R, 'flow_graph/plant_flow_graph.json'))); rows = []
    for n in sorted(g['nodes'], key=lambda n: n['unit_id']):
        p = n.get('params') or {}; ds = p.get('design') or {}
        P = p.get('design_kPa'); T = ds.get('T_C'); D = ds.get('D_mm'); t = ds.get('wall_mm') or ds.get('t_nom_mm') or 0
        ID = (D - 2*t) if D else None
        if n['unit_id'] in MACHINES: cls, why = 'Machine casing (outside Section VIII)', 'U-1(c)(2)(c): ' + MACHINES[n['unit_id']]
        elif P is None: cls, why = 'not a vessel (no design pressure on the graph)', '-'
        elif P <= 103.0: cls, why = 'Atmospheric', 'U-1(c)(2)(h): <= 103 kPa g'
        elif ID is not None and ID <= 152.0: cls, why = 'B31.3 piping component', f'U-1(c)(2)(j): ID {ID:.0f} mm <= 152 mm'
        elif ID is None: cls, why = 'Section VIII-1 (ID not yet sized)', f'{P:.0f} kPa g > 103; size from its unit design'
        else: cls, why = 'Section VIII-1', f'{P:.0f} kPa g, ID {ID:.0f} mm'
        rows.append((n['unit_id'], n.get('sector_id'), P, T, ID, cls, why))
    STAMP = {'Atmospheric': ('none (API 650/620 or DVS 2205 intent; no Code stamp)', 'fill test with water to the top of the shell'),
             'B31.3 piping component': ('none (piping carries no Certification Mark, ASME_B31_3)', 'hydrostatic 1.5 x design (ASME_B31_3 345.4.2); 341 examination'),
             'Machine casing (outside Section VIII)': ('none (part of the machine, ASME_VIII1_U1 U-1(c)(2)(c))', 'casing hydrotest 1.5 x design by the builder'),
             'Section VIII-1': ('U stamp by a Certificate Holder and NB registration if the jurisdiction requires (ASME_VIII1_UG UG-116)', 'hydrostatic 1.3 x MAWP (ASME_VIII1_UG UG-99(b))'),
             'Section VIII-1 (ID not yet sized)': ('U stamp pending size', 'UG-99(b) pending size')}
    st = lambda cl: STAMP.get(cl, ('-', '-'))
    c = collections.Counter(r[5] for r in rows)
    ph = [n['unit_id'] for n in g['nodes'] if 'hold-up' in str(((n.get('params') or {}).get('relief_basis') or {}).get('design_case', ''))]
    md = ['# In-house code intent per unit', '', 'Document number: AQS-ASME-002', 'Revision: B', 'Date: 2026-10-16',
          'Authority: AQS-PLAN-007 X-MFG-40 (replaces the "Vendor" class of AQS-ASME-001 section 3). Generated by `docs-authority/_asme_class.py` from the graph. Study; no Code stamp.', '',
          'Rules from the Section VIII-1 scope (ASME_VIII1_U1): design pressure at or below 103 kPa g is outside Section VIII (atmospheric tanks); a vessel of inside diameter at or below 152 mm is outside Section VIII by size and is designed as a piping component (ASME_B31_3), with the UG-27 wall check already made in AQS-DUTY-062; everything else is Section VIII Division 1, designed in-house.', '',
          '| Class | Units |', '|---|---|'] + [f'| {k} | {v} |' for k, v in sorted(c.items())] + ['',
          f"Atmospheric design pressure is set from the actual cases by the vent stage (A-M-174): 4 x the open-vent dP for the vapour space plus the full-height hydrostatic head at SG 1.25. {len(ph)} atmospheric units have no sized height yet; their liquid head comes from a hold-up volume (A-M-182: 2 d for stores, 1 d for process units, H/D 1.5) until their unit sizing replaces it. Units with no liquid inflow carry the vapour case alone. Among the X-MFG-40 named units, GLASS_BURNOUT (rotary kiln), ALK_SCRUBBER, ZNBR2_BR2_REGEN (Br2 tower) and OIL_FRAC run at or near atmospheric pressure by process and stay atmospheric; the cold box CRYO_ASU does not: its compressor and column pressures are set by X-MFG-33 and it is reclassified when that design issues.", '',
          '## Stamp and test requirement (X-COD-03)', '', '| Class | Stamp | Pressure test |', '|---|---|---|'] + [f'| {k} | {st(k)[0]} | {st(k)[1]} |' for k in sorted(c) if k in STAMP] + ['',
          f"Pressurised nodes needing a U stamp: {sum(1 for r in rows if r[5].startswith('Section VIII-1'))}. Every pressurised node is a B31.3 component or a machine casing, so no Code stamp is required; the jurisdictional review (Texas boiler and pressure vessel rules) is an X-COD-01 item.", '',
          '| Unit | Sector | Design kPa g | Design T C | ID mm | Code intent | Basis | Stamp | Test |', '|---|---|---|---|---|---|---|---|---|']
    md += [f"| {u} | {s} | {'' if P is None else f'{P:.1f}'} | {'' if T is None else T} | {'' if ID is None else f'{ID:.0f}'} | {cl} | {w} | {st(cl)[0]} | {st(cl)[1]} |" for u, s, P, T, ID, cl, w in rows]
    open(os.path.join(R, 'docs-authority/ASME_CODE_INTENT.md'), 'w').write('\n'.join(md) + '\n'); print(dict(c))
if __name__ == '__main__': main()
